package nhom10.phonenest.service;
import lombok.RequiredArgsConstructor; import nhom10.phonenest.dto.DanhGiaDto; import nhom10.phonenest.entity.*; import nhom10.phonenest.enums.*; import nhom10.phonenest.exception.AppException; import nhom10.phonenest.repository.*; import nhom10.phonenest.util.IdGenerator; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.time.*; import java.util.*;
@Service @RequiredArgsConstructor @Transactional public class DanhGiaService{private static final int HAN=30;private final DanhGiaRepository repo;private final DonHangRepository donRepo;private final SanPhamRepository spRepo;private final KhachHangRepository khRepo;private final YeuCauDoiTraRepository dtRepo;private final NhatKyHoatDongService nhatKyHoatDongService;
 public DanhGiaDto tao(String maKh,DanhGiaDto.Request r){DonHang don=donCuaToi(maKh,r.maDonHang());ChiTietDonHang c=line(don,r.maSanPham());String ly=lyDo(don,c);if(ly!=null)throw new AppException(HttpStatus.BAD_REQUEST,ly);String nd=r.noiDungBinhLuan()==null?"":r.noiDungBinhLuan().trim();if(r.diemSao()<=2&&nd.length()<10)throw new AppException(HttpStatus.BAD_REQUEST,"Với đánh giá 1 - 2 sao, vui lòng cho biết lý do (ít nhất 10 ký tự)");DanhGia d=new DanhGia();d.setMaDanhGia(IdGenerator.next("DG"));d.setKhachHang(khRepo.findById(maKh).orElseThrow());d.setChiTietDonHang(c);d.setSanPham(c.getPhienBan().getSanPham());d.setDiemSao(r.diemSao());d.setNoiDungBinhLuan(nd.isEmpty()?null:nd);d.setHinhAnhThucTe(r.hinhAnhThucTe());d.setNgayDanhGia(LocalDateTime.now());d=repo.save(d);capNhatDiem(d.getSanPham().getMaSanPham());return dto(d);}
 public List<DanhGiaDto.TrangThai> theoDonHang(String maKh,String ma){DonHang d=donCuaToi(maKh,ma);return d.getChiTiet().stream().map(c->{var da=repo.findByChiTietDonHangMaChiTiet(c.getMaChiTiet());String ly=da.isPresent()?"Bạn đã đánh giá sản phẩm này":lyDo(d,c);return new DanhGiaDto.TrangThai(c.getPhienBan().getSanPham().getMaSanPham(),ly==null,ly==null?"":ly,da.map(this::dto).orElse(null));}).toList();}
 private String lyDo(DonHang d,ChiTietDonHang c){if(d.getTrangThai()!=TrangThaiDonHang.DA_GIAO)return "Chỉ đánh giá được khi đơn hàng đã giao thành công";if(repo.findByChiTietDonHangMaChiTiet(c.getMaChiTiet()).isPresent())return "Bạn đã đánh giá sản phẩm này";boolean doi=dtRepo.findByDonHangMaDonHangOrderByNgayTaoDesc(d.getMaDonHang()).stream().anyMatch(y->y.getTrangThai()!=TrangThaiDoiTra.TU_CHOI);if(doi)return "Đơn hàng đang có yêu cầu đổi trả / hoàn tiền";LocalDateTime g=d.getNgayGiao()!=null?d.getNgayGiao():d.getNgayCapNhat();if(g!=null&&LocalDateTime.now().isAfter(g.plusDays(HAN)))return "Đã quá hạn đánh giá ("+HAN+" ngày)";return null;}
 private ChiTietDonHang line(DonHang d,String ma){return d.getChiTiet().stream().filter(c->c.getPhienBan().getSanPham().getMaSanPham().equals(ma)||c.getPhienBan().getMaPhienBan().equals(ma)).findFirst().orElseThrow(()->new AppException(HttpStatus.BAD_REQUEST,"Sản phẩm không có trong đơn hàng"));}
 private DonHang donCuaToi(String kh,String ma){return donRepo.findById(ma).filter(d->d.getKhachHang().getMaKh().equals(kh)).orElseThrow(()->new AppException(HttpStatus.NOT_FOUND,"Không tìm thấy đơn hàng"));}
 public List<DanhGiaDto> theoSanPham(String ma){return repo.findBySanPhamMaSanPhamOrderByNgayDanhGiaDesc(ma).stream().map(this::dto).toList();} public List<DanhGiaDto> cuaToi(String ma){return repo.findByKhachHangMaKhOrderByNgayDanhGiaDesc(ma).stream().map(this::dto).toList();} public List<DanhGiaDto> tatCa(){return repo.findAllByOrderByNgayDanhGiaDesc().stream().map(this::dto).toList();} public void xoa(String ma){DanhGia d=repo.findById(ma).orElseThrow(()->new AppException(HttpStatus.NOT_FOUND,"Không tìm thấy đánh giá"));String sp=d.getSanPham().getMaSanPham();Map<String,Object> duLieuTruoc=snapshot(d);repo.delete(d);repo.flush();capNhatDiem(sp);nhatKyHoatDongService.ghi(HanhDongAudit.DELETE_REVIEW,LoaiDoiTuongAudit.REVIEW,ma,duLieuTruoc,null);}
 private Map<String,Object> snapshot(DanhGia d){Map<String,Object> duLieu=new LinkedHashMap<>();duLieu.put("maSanPham",d.getSanPham()!=null?d.getSanPham().getMaSanPham():null);duLieu.put("diemSao",d.getDiemSao());duLieu.put("noiDungBinhLuan",d.getNoiDungBinhLuan());return duLieu;}
 private void capNhatDiem(String ma){Double tb=repo.trungBinh(ma);spRepo.findById(ma).ifPresent(s->s.setDiemDanhGiaTb(tb==null?BigDecimal.ZERO:BigDecimal.valueOf(tb).setScale(1,RoundingMode.HALF_UP)));}
 private DanhGiaDto dto(DanhGia d){return new DanhGiaDto(d.getMaDanhGia(),d.getChiTietDonHang().getDonHang().getMaDonHang(),d.getSanPham().getMaSanPham(),d.getSanPham().getTenMay(),d.getKhachHang().getHoTen(),d.getDiemSao(),d.getNoiDungBinhLuan(),d.getHinhAnhThucTe(),d.getNgayDanhGia().toLocalDate());}
}
